/// <summary>
/// Extension of table <t>MarkupAutoTable</t>
/// </summary>
[ExtensionOf(tableStr(MarkupAutoTable))]
final class AVAMarkupAutoTableDbt_Extension
{
}

Method.Source:
/// <summary>
/// find MarkupAutoTable record by RecId
/// </summary>
/// <param name = "_recId">RecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>MarkupAutoTable</returns>
public static MarkupAutoTable avaFindByRecId(
    RecId _recId,
    boolean _selectForUpdate = false)
{
    MarkupAutoTable markupAutoTableLoc;

    if(_selectForUpdate)
    {
        markupAutoTableLoc.selectForUpdate(true);
    }

    select firstonly markupAutoTableLoc
        where markupAutoTableLoc.RecId == _recId;

    return markupAutoTableLoc;
}

/// <summary>
/// find record by recid and tableid
/// </summary>
/// <param name = "_recId">recid</param>
/// <param name = "_tableId">tableid</param>
/// <returns>MarkupAutoTable record</returns>
public static MarkupAutoTable findByRecIdAndTableId(RecId _recId, TableId _tableId)
{
    MarkupAutoTable avaMarkupAutoTable;

    select firstonly avaMarkupAutoTable
        where avaMarkupAutoTable.RecId == _recId
            && avaMarkupAutoTable.TableId == _tableId;

    return avaMarkupAutoTable;
}
